package com.controldecortes.controller;
import com.controldecortes.domain.ActiveStatus; import com.controldecortes.dto.ApiDtos.*; import com.controldecortes.service.CutService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/cuts") public class CutController { private final CutService service; public CutController(CutService s){service=s;} @GetMapping public Object list(@RequestParam(required=false) Long supplierId){return service.list(supplierId);} @GetMapping("/active") public List<CutResponse> active(@RequestParam Long supplierId){return service.activeBySupplier(supplierId);} @PostMapping public ResponseEntity<CutResponse> create(@Valid @RequestBody CutRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PutMapping("/{id}") public CutResponse update(@PathVariable Long id,@Valid @RequestBody CutRequest r){return service.update(id,r);} @PatchMapping("/{id}/active") public CutResponse active(@PathVariable Long id,@RequestParam boolean value){return service.setActive(id,value);} @PatchMapping("/{id}/status") public CutResponse status(@PathVariable Long id,@RequestParam ActiveStatus value){return service.setStatus(id,value);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
